import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-g2-3/bot.mjs';

const tokyo = (over = {}) => ({ id: 'u_1', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3, ...over });
const at = (s) => new Date(s);

test('quiet hours wrap midnight in user zone', () => {
  const g = createPushGate();
  const u = tokyo();
  assert.deepEqual(g.attempt(u, at('2026-10-22T23:30:00+09:00')), { allowed: false, reason: 'quiet_hours' });
  assert.deepEqual(g.attempt(u, at('2026-10-22T22:00:00+09:00')), { allowed: false, reason: 'quiet_hours' });
  assert.deepEqual(g.attempt(u, at('2026-10-23T06:59:00+09:00')), { allowed: false, reason: 'quiet_hours' });
  assert.deepEqual(g.attempt(u, at('2026-10-23T07:00:00+09:00')), { allowed: true, reason: null });
  assert.deepEqual(g.attempt(u, at('2026-10-22T21:59:00+09:00')), { allowed: false, reason: 'min_gap' }); // 07:00 push -> min gap, not quiet
});

test('quiet hours use the user zone, not UTC or server zone', () => {
  const g = createPushGate();
  // 14:30 UTC = 23:30 Tokyo (quiet) but 05:30 Istanbul-equivalent is not quiet in Istanbul zone
  assert.equal(g.attempt(tokyo(), at('2026-10-22T14:30:00Z')).reason, 'quiet_hours');
  assert.equal(g.attempt(tokyo({ id: 'u_2', timeZone: 'Europe/Istanbul' }), at('2026-10-22T14:30:00Z')).allowed, true); // 17:30 Istanbul
});

test('non-wrapping quiet window', () => {
  const g = createPushGate();
  const u = { id: 'n', timeZone: 'Europe/Istanbul', quietStart: '13:00', quietEnd: '14:00', dailyCap: 9 };
  assert.equal(g.attempt(u, at('2026-10-22T10:00:00Z')).allowed, false); // 13:00 Istanbul
  assert.equal(g.attempt(u, at('2026-10-22T10:59:00Z')).reason, 'quiet_hours');
  assert.equal(g.attempt(u, at('2026-10-22T11:00:00Z')).allowed, true); // 14:00 Istanbul, end exclusive
});

test('equal start and end means no quiet window; null means none', () => {
  const g = createPushGate();
  assert.equal(g.attempt({ id: 'a', timeZone: 'UTC', quietStart: '00:00', quietEnd: '00:00', dailyCap: 5 }, at('2026-10-22T03:00:00Z')).allowed, true);
  assert.equal(g.attempt({ id: 'b', timeZone: 'UTC', quietStart: null, quietEnd: null, dailyCap: 5 }, at('2026-10-22T03:00:00Z')).allowed, true);
});

test('daily cap counts the user local calendar day, not UTC', () => {
  const g = createPushGate();
  const u = tokyo({ dailyCap: 2 });
  // 05:00 and 06:30 JST on Oct 23 (UTC date Oct 22)
  assert.equal(g.attempt(u, at('2026-10-22T20:00:00Z')).allowed, true);
  assert.equal(g.attempt(u, at('2026-10-22T21:30:00Z')).allowed, true);
  // 19:00 JST Oct 23 (UTC date Oct 23): same local day, cap hit
  assert.equal(g.attempt(u, at('2026-10-23T10:00:00Z')).reason, 'daily_cap_reached');
});

test('new local day resets the cap, even 70 min after the last push', () => {
  const g = createPushGate();
  const u = tokyo({ dailyCap: 1, quietStart: null, quietEnd: null });
  assert.equal(g.attempt(u, at('2026-10-22T14:50:00Z')).allowed, true); // 23:50 JST Oct 22
  assert.equal(g.attempt(u, at('2026-10-22T16:00:00Z')).reason, 'daily_cap_reached'); // 01:00 JST Oct 23 is new day
});

test('new day allows push again', () => {
  const g = createPushGate();
  const u = tokyo({ dailyCap: 1, quietStart: null, quietEnd: null });
  assert.equal(g.attempt(u, at('2026-10-22T14:50:00Z')).allowed, true); // 23:50 JST Oct 22
  assert.deepEqual(g.attempt(u, at('2026-10-22T16:00:00Z')), { allowed: true, reason: null }); // 01:00 JST Oct 23
});

test('min gap is 60 minutes, measured from the last push', () => {
  const g = createPushGate();
  const u = { id: 'g', timeZone: 'UTC', quietStart: null, quietEnd: null, dailyCap: 10 };
  assert.equal(g.attempt(u, at('2026-10-22T09:00:00Z')).allowed, true);
  assert.equal(g.attempt(u, at('2026-10-22T09:30:00Z')).reason, 'min_gap');
  assert.equal(g.attempt(u, at('2026-10-22T09:59:59Z')).reason, 'min_gap');
  assert.equal(g.attempt(u, at('2026-10-22T10:00:00Z')).allowed, true);
});

test('blocked attempts do not count as sent', () => {
  const g = createPushGate();
  const u = { id: 'x', timeZone: 'UTC', quietStart: null, quietEnd: null, dailyCap: 1 };
  assert.equal(g.attempt(u, at('2026-10-22T09:00:00Z')).allowed, true);
  assert.equal(g.attempt(u, at('2026-10-22T09:10:00Z')).reason, 'min_gap');
  assert.equal(g.attempt(u, at('2026-10-22T09:20:00Z')).reason, 'min_gap');
  assert.equal(g.attempt(u, at('2026-10-22T11:00:00Z')).reason, 'daily_cap_reached');
});

test('dailyCap 0 blocks everything; quiet check comes first', () => {
  const g = createPushGate();
  assert.equal(g.attempt({ id: 'z', timeZone: 'UTC', quietStart: null, quietEnd: null, dailyCap: 0 }, at('2026-10-22T09:00:00Z')).reason, 'daily_cap_reached');
  assert.equal(g.attempt({ id: 'q', timeZone: 'UTC', quietStart: '08:00', quietEnd: '10:00', dailyCap: 0 }, at('2026-10-22T09:00:00Z')).reason, 'quiet_hours');
});

test('settings are read per call; users and gates are independent', () => {
  const g = createPushGate();
  assert.equal(g.attempt({ id: 'p', timeZone: 'UTC', quietStart: null, quietEnd: null, dailyCap: 1 }, at('2026-10-22T09:00:00Z')).allowed, true);
  // same user, cap raised on this call, but min gap still applies
  assert.equal(g.attempt({ id: 'p', timeZone: 'UTC', quietStart: null, quietEnd: null, dailyCap: 5 }, at('2026-10-22T09:10:00Z')).reason, 'min_gap');
  // other user unaffected
  assert.equal(g.attempt({ id: 'other', timeZone: 'UTC', quietStart: null, quietEnd: null, dailyCap: 1 }, at('2026-10-22T09:10:00Z')).allowed, true);
  // a fresh gate has no history
  assert.equal(createPushGate().attempt({ id: 'p', timeZone: 'UTC', quietStart: null, quietEnd: null, dailyCap: 1 }, at('2026-10-22T09:10:00Z')).allowed, true);
});

test('reason codes are distinct snake_case', () => {
  const codes = new Set(['quiet_hours', 'daily_cap_reached', 'min_gap']);
  assert.equal(codes.size, 3);
  for (const c of codes) assert.match(c, /^[a-z]+(_[a-z]+)*$/);
});

test('invalid input throws', () => {
  const g = createPushGate();
  const ok = tokyo();
  const now = at('2026-10-22T09:00:00Z');
  assert.throws(() => g.attempt({ ...ok, timeZone: 'Mars/Olympus' }, now), RangeError);
  assert.throws(() => g.attempt({ ...ok, quietStart: '25:00' }, now), TypeError);
  assert.throws(() => g.attempt({ ...ok, dailyCap: -1 }, now), TypeError);
  assert.throws(() => g.attempt({ ...ok, dailyCap: 1.5 }, now), TypeError);
  assert.throws(() => g.attempt({ ...ok, id: '' }, now), TypeError);
  assert.throws(() => g.attempt(ok, new Date('nope')), TypeError);
  assert.throws(() => g.attempt(ok, 1234), TypeError);
});

test('result shape is exact', () => {
  const g = createPushGate();
  const r = g.attempt({ id: 's', timeZone: 'UTC', quietStart: null, quietEnd: null, dailyCap: 1 }, at('2026-10-22T09:00:00Z'));
  assert.deepEqual(Object.keys(r).sort(), ['allowed', 'reason']);
  assert.deepEqual(r, { allowed: true, reason: null });
});
EOF
